CREATE TABLE email_outbox (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, operation_key VARCHAR(191) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, message_kind VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, recipient_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, payload_encrypted MEDIUMTEXT NOT NULL, status ENUM('pending','uncertain','sent') NOT NULL DEFAULT 'pending', claim_token CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL, attempt_count INT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), sent_at DATETIME(6) NULL, PRIMARY KEY (id), UNIQUE KEY uq_email_outbox_operation (operation_key), KEY idx_email_outbox_status_created (status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
